import { Component, Show } from "solid-js";
import { JSX } from "solid-js/jsx-runtime";

import { L10n } from "#core/ui-next/components/l10n.jsx";

export interface ProgressBarProps extends JSX.HTMLAttributes<HTMLElement> {
	titleText?: string;
	progressString?: string;
	progressPercent: number;
}

export const ProgressBar: Component<ProgressBarProps> = (props) => {
	return (
		<div
			class={`flex flex-col w-full ${props.class ?? ""}`}
			data-name="Progress-Bar"
		>
			<div class="flex flex-row w-full mb-2">
				<Show when={props.titleText != undefined}>
					<div class="text-secondary self-start mr-3">
						<L10n.Compose text={props.titleText!} />
					</div>
				</Show>
				<Show when={props.progressString}>
					<div class="flex text-secondary self-end">{props.progressString}</div>
				</Show>
			</div>
			<div
				class="w-full h-4"
				style={{
					"background-color": "rgba(0,0,0,0.4)",
					"border-color": "rgba(64,68,83,1)",
					"border-width": "pixels(1)",
				}}
			>
				<div
					class="h-3 py-0\.5 self-start"
					style={{
						"background-color": "rgba(58, 115, 65, 1)",
						width: props.progressPercent.toString() + "%",
					}}
				/>
			</div>
		</div>
	);
};
